<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { asignarActividad, eliminarActividad, listarColaboradores, obtenerProductividad, type Actividad, type Colaborador } from '../services/productividad'
const users=ref<Colaborador[]>([]),selected=ref<Colaborador|null>(null),activities=ref<Actividad[]>([]),search=ref(''),description=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),page=ref(1),lastPage=ref(1),total=ref(0)
const completed=computed(()=>activities.value.filter(x=>x.atendido).length),progress=computed(()=>activities.value.length?Math.round(completed.value/activities.value.length*100):0),initials=(name:string)=>name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()
async function load(target=1){loading.value=true;error.value='';try{const r=await listarColaboradores(search.value,target);users.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(user:Colaborador){loading.value=true;error.value='';try{const r=await obtenerProductividad(user.id);selected.value=r.colaborador;activities.value=r.actividades}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(!selected.value)return;const value=description.value.trim();if(value.length<20){error.value='La descripción debe contener al menos 20 caracteres.';return}saving.value=true;error.value='';try{await asignarActividad(selected.value.id,value);description.value='';success.value='La actividad fue asignada correctamente.';await open(selected.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:Actividad){if(!selected.value||!confirm(`¿Eliminar la actividad #${item.id}?`))return;error.value='';try{await eliminarActividad(selected.value.id,item.id);success.value='La actividad fue eliminada.';await open(selected.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Productividad</nav><header class="hero"><div class="mark">RH</div><div><small>MIA · RECURSOS HUMANOS</small><h1>Productividad</h1><p>Asigna actividades y consulta el avance de los colaboradores.</p></div><div v-if="!selected" class="search"><input v-model.trim="search" placeholder="Nombre o usuario" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button></div></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p>
<section v-if="selected" class="detail"><button class="back" @click="selected=null;activities=[]">← Volver a colaboradores</button><div class="columns"><aside><article class="profile"><img v-if="selected.imagen_url" :src="selected.imagen_url" alt=""><div v-else class="avatar">{{initials(selected.nombre_completo)}}</div><h2>{{selected.nombre_completo}}</h2><span>@{{selected.username}} · DNI {{selected.dni}}</span><small v-if="selected.fecha_nacimiento">{{selected.fecha_nacimiento}} · {{selected.sexo}}</small></article><article class="metric"><div><small>ACTIVIDADES CULMINADAS</small><b>{{completed}} / {{activities.length}}</b></div><strong>{{progress}}%</strong><div class="bar"><i :style="{width:`${progress}%`}"></i></div></article></aside><main><form class="assign" @submit.prevent="save"><small>ASIGNACIÓN DE TRABAJO</small><h2>Nueva actividad</h2><label>Descripción *<textarea v-model="description" rows="5" placeholder="Describa la actividad que realizará el colaborador"></textarea><span>{{description.trim().length}} / mínimo 20 caracteres</span></label><button :disabled="saving">{{saving?'Registrando…':'Asignar actividad'}}</button></form></main></div><section class="tasks"><header><div><small>SEGUIMIENTO</small><h2>Actividades asignadas</h2></div><span>{{activities.length}} registros</span></header><div v-if="!activities.length" class="empty">El colaborador no tiene actividades asignadas.</div><div v-else class="task-grid"><article v-for="item in activities" :key="item.id" :class="{done:item.atendido}"><header><b>#{{item.id}} · {{item.seccion}}</b><span>{{item.atendido?'CULMINADA':'EN EJECUCIÓN'}}</span></header><small>{{item.fecha_registro}} · {{item.registrado_por}}</small><p>{{item.descripcion}}</p><footer><small v-if="item.fecha_atencion">Atendida: {{item.fecha_atencion}}</small><button v-if="!item.atendido" @click="remove(item)">Eliminar</button></footer></article></div></section></section>
<template v-else><section class="summary"><div><small>COLABORADORES ACTIVOS</small><b>{{total}}</b></div><div><small>MOSTRADOS</small><b>{{users.length}}</b></div><div><small>PÁGINA</small><b>{{page}} / {{lastPage}}</b></div></section><div v-if="loading" class="empty">Cargando colaboradores…</div><div v-else-if="!users.length" class="empty">No se encontraron colaboradores.</div><section v-else class="people"><article v-for="user in users" :key="user.id"><img v-if="user.imagen_url" :src="user.imagen_url" alt=""><div v-else class="avatar">{{initials(user.nombre_completo)}}</div><h2>{{user.nombre_completo}}</h2><span>@{{user.username}}</span><div class="mini"><b>{{user.total_culminadas}} / {{user.total_tareas}}</b><small>actividades culminadas</small></div><button @click="open(user)">Ver tareas y avances →</button></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer></template></div></template>
<style scoped>
