lor:#7b898f;font-size:.5rem}.mini{margin:13px 0;display:grid;text-align:center}.mini b{font-size:.8rem}.mini small{color:#879399;font-size:.45rem}.pager{margin-top:12px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.pager button:disabled{opacity:.45}.detail{margin-top:11px}.back{margin-bottom:8px;color:#637178;background:#e9eef0}.columns{display:grid;grid-template-columns:.8fr 1.5fr;gap:9px}.profile,.metric,.assign,.tasks{padding:17px;border-radius:10px;background:#fff}.profile{display:grid;justify-items:center}.profile small{margin-top:4px;color:#89959a}.metric{margin-top:9px;display:grid;grid-template-columns:1fr auto}.metric div:first-child{display:grid}.metric b{font-size:1.1rem}.metric strong{font-size:1rem;color:#349b74}.bar{grid-column:1/-1;height:7px;margin-top:10px;border-radius:5px;overflow:hidden;background:#e7ecee}.bar i{height:100%;display:block;background:#349b74}.assign h2,.tasks h2{margin:2px 0 12px;font-size:.78rem}.assign label{display:grid;gap:4px;font-size:.52rem}.assign textarea{width:100%;resize:vertical}.assign label span{color:#8b979c;text-align:right;font-size:.45rem}.assign button{margin-top:10px;float:right}.tasks{margin-top:9px}.tasks>header{display:flex;align-items:center}.tasks>header>span{margin-left:auto;font-size:.5rem}.task-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.task-grid article{padding:11px;border-top:3px solid #e4a73c;border-radius:7px;background:#f6f8f9}.task-grid article.done{border-color:#349b74}.task-grid header,.task-grid footer{display:flex;align-items:center;justify-content:space-between}.task-grid b{font-size:.5rem}.task-grid header span{padding:3px 5px;border-radius:8px;color:#96640c;background:#fff1cf;font-size:.4rem}.task-grid .done header span{color:#277155;background:#e1f4eb}.task-grid>article>small{display:block;margin-top:5px;color:#879399}.task-grid p{min-height:42px;font-size:.52rem;line-height:1.45}.tasks button{padding:5px 7px;background:#db5b61}.tasks .empty{padding:25px;background:#f6f8f9}@media(max-width:850px){.hero{flex-wrap:wrap}.search{width:100%;margin-left:0}.search input{flex:1}.summary,.people,.columns,.task-grid{grid-template-columns:1fr}}
